-- ============================================================================
--  TravaillerEnCi — Migration Supabase 0038
--  Privileges service_role sur schema public
--\n\n-- Cette migration s'assure que service_role dispose des privilèges minimum\n-- nécessaires au fonctionnement de l'application, sans jamais nuire à la sécurité.\n--\n-- Contexte : avant le sprint 1.2, service_role ne disposait que de\n-- TRUNCATE/REFERENCES/TRIGGER, provoquant des erreurs 42501 sur toutes les\n-- opérations d'écriture. Un GRANT manuel avait été nécessaire.\n--\n-- Cette migration formalise et sécurise cet octroi via le versionnement.\n-- ============================================================================\n\n-- 1. Vérifier si les colonnes existent déjà (idempotence)\nDO $$\nDECLARE\n    has_select BOOLEAN;\n    has_insert BOOLEAN;\n    has_update BOOLEAN;\n    has_delete BOOLEAN;\nBEGIN\n    -- Vérifier les privilèges existants\n    SELECT has_table_privilege('service_role', 'public', 'SELECT')\n      INTO has_select;\n    SELECT has_table_privilege('service_role', 'public', 'INSERT')\n      INTO has_insert;\n    SELECT has_table_privilege('service_role', 'public', 'UPDATE')\n      INTO has_update;\n    SELECT has_table_privilege('service_role', 'public', 'DELETE')\n      INTO has_delete;\n\n    -- N'octroyer que ce qui manque\n    IF NOT has_select THEN\n        GRANT SELECT ON ALL TABLES IN SCHEMA public TO service_role;\n        RAISE NOTICE 'GRANT SELECT ajouté à service_role';\n    END IF;\n    IF NOT has_insert THEN\n        GRANT INSERT ON ALL TABLES IN SCHEMA public TO service_role;\n        RAISE NOTICE 'GRANT INSERT ajouté à service_role';\n    END IF;\n    IF NOT has_update THEN\n        GRANT UPDATE ON ALL TABLES IN SCHEMA public TO service_role;\n        RAISE NOTICE 'GRANT UPDATE ajouté à service_role';\n    END IF;\n    IF NOT has_delete THEN\n        GRANT DELETE ON ALL TABLES IN SCHEMA public TO service_role;\n        RAISE NOTICE 'GRANT DELETE ajouté à service_role';\n    END IF;\nEND $$;\n\n-- 2. S'assurer que les séquencesowned par public sont aussi accessibles\nDO $$\nBEGIN\n    GRANT USAGE, SELECT ON ALL SEQUENCES IN SCHEMA public TO service_role;\n    RAISE NOTICE 'GRANT séquences ajouté à service_role';\nEND $$;\n\n-- 3. Documenter l'objectif de cette migration\nCOMMENT ON DATABASE IS 'Migration 0038 : privileges service_role formalisées. Voir rollback ci-dessous.';\n\n-- Rollback : retirer TOUS les privilèges DML de service_role\n-- Attention : cela rendra l'application inopérante en lecture/écriture\nDO $$\nBEGIN\n    REVOKE DELETE, UPDATE, INSERT, SELECT ON ALL TABLES IN SCHEMA public FROM service_role;\n    REVOKE USAGE, SELECT ON ALL SEQUENCES IN SCHEMA public FROM service_role;\n    RAISE NOTICE 'Tous les droits DML retirés de service_role (rollback migration 0038)';\nEND $$;\n